    fun variants(emoji: String): List<String> {
        if (emoji !in skinTone) return emptyList()
        val baseLength = Character.charCount(emoji.codePointAt(0))
        val base = emoji.substring(0, baseLength)
        val suffix = emoji.substring(baseLength).removePrefix("\uFE0F")
        return listOf(emoji) + (0x1F3FB..0x1F3FF).map {
            base + String(Character.toChars(it)) + suffix
        }
    }
    fun description(emoji: String): String = emoji.codePoints().toArray()
        .filter { it != 0xFE0F && it != 0x200D }.joinToString(", ") { Character.getName(it) ?: "Emoji" }
